#!/bin/zsh
# Uploads three Warwick images to Shopify staged upload targets (policies expire 2026-11-11 13:55Z).
cd "$(dirname "$0")/up" || exit 1
up() {
  curl -s -o /dev/null -w "$1 %{http_code}\n" -X POST "https://shopify-staged-uploads.storage.googleapis.com/" \
    -F "Content-Type=image/jpeg" -F "success_action_status=201" -F "acl=private" \
    -F "key=$2" -F "x-goog-date=20261110T135506Z" \
    -F "x-goog-credential=merchant-assets@shopify-tiers.iam.gserviceaccount.com/20261110/auto/storage/goog4_request" \
    -F "x-goog-algorithm=GOOG4-RSA-SHA256" -F "x-goog-signature=$3" -F "policy=$4" -F "file=@$1"
}
up warwick-front-no-drawers.jpg "tmp/10152577/files/0643174a-6fd7-4086-b07f-c9767fb6452f/warwick-front-no-drawers.jpg" \
  "" \
  ""
up warwick-room-no-drawers.jpg "tmp/10152577/files/25c68d03-e5c4-4b3b-8ac5-03e72f83be1f/warwick-room-no-drawers.jpg" \
  "" \
  ""
up warwick-walnut-front.jpg "tmp/10152577/files/2adedfe4-523b-41f9-bda2-6a0fe166383d/warwick-walnut-front.jpg" \
  "" \
  ""
